package com.example.leetcodetrainer.adaptive.service;
import com.example.leetcodetrainer.adaptive.domain.AttemptRecursiveContract; import com.example.leetcodetrainer.adaptive.repository.AttemptRecursiveContractRepository; import com.example.leetcodetrainer.attempt.service.AttemptService; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class AttemptRecursiveContractService { private final AttemptRecursiveContractRepository contracts; private final AttemptService attempts; private final Clock clock; public AttemptRecursiveContractService(AttemptRecursiveContractRepository c,AttemptService a,Clock clock){contracts=c;attempts=a;this.clock=clock;} public Optional<AttemptRecursiveContract> find(UUID id){return contracts.findById(id);} public void save(UUID id,String functionContract,String baseCase,String subproblems,String compositionRule){attempts.get(id);var now=Instant.now(clock);var contract=contracts.findById(id).orElseGet(()->new AttemptRecursiveContract(id,now));contract.save(functionContract,baseCase,subproblems,compositionRule,now);contracts.save(contract);} }
